args.sparql:
SELECT DISTINCT ?spouse ?spouseLabel WHERE {
  {
    dbr:Nicole_Briscoe dbo:spouse ?spouse .
  }
  UNION
  {
    dbr:Nicole_Briscoe dbp:spouse ?spouse .
  }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel FILTER(lang(?spouseLabel) = 'en') }
}

SELECT DISTINCT ?country ?countryLabel WHERE {
  BIND(dbr:Ryan_Briscoe AS ?spouse)
  {
    ?spouse dbo:nationality ?country .
  }
  UNION
  {
    ?spouse dbp:nationality ?country .
  }
  UNION
  {
    ?spouse dbo:birthPlace ?place .
    ?place dbo:country ?country .
  }
  UNION
  {
    ?spouse dbp:birthPlace ?place .
    ?place dbo:country ?country .
  }
  OPTIONAL { ?country rdfs:label ?countryLabel FILTER(lang(?countryLabel) = 'en') }
}

